import { chapters } from './chapters.js';
import { renderVisual, bindVisual } from './visuals.js';
import { resources, glossary, lessonTemplate } from './resources.js';
import { sourceMap, labResults, labRegistry } from './generated-data.js';
import { zeroSteps } from './zero.js';
import { bindLessonDemos, lessonDemos } from './lesson-demo.js';
import { sourceLessons } from './source-lessons.js';
import { renderZeroPage, renderSourcePage, renderChapterBridge, plainFlow } from './beginner-ui.js';
import { officialPages, renderOfficialPage } from './official-docs.js';

const $=s=>document.querySelector(s), app=$('#app');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const inline=s=>escape(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
const chapterLink=id=>`#/learn/${id}`;
const storageKey='loongsuite-field-guide-v1';
let state={checks:{},answers:{},done:[],notes:{},last:'orientation'};
try{const old=JSON.parse(localStorage.getItem(storageKey)||'null');if(old&&typeof old==='object')state={...state,...old};}catch{}
let currentRoute='',toastTimer;
let disposeLessonDemos=()=>{};
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('浏览器未允许保存；可导出笔记。');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
const number=id=>String(chapters.findIndex(c=>c.id===id)+1).padStart(2,'0');
const codeBlock=(code,lang='text',numbered=true)=>`<div class="code-frame"><div class="code-bar"><span>${escape(lang.toUpperCase())}</span><button class="copy-btn" data-copy>复制代码</button></div><pre><code>${escape(code).split('\n').map((s,i)=>`${numbered?`<span class="line-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>`:''}${s}`).join('\n')}</code></pre><span hidden data-raw>${escape(code)}</span></div>`;
function footer(){return `<footer class="footer"><span>LoongSuite Go Field Guide · 中文学习手册</span><span>源码固定 v1.15.0 / cac4009 · 2026-10-29 实例动画更新</span></footer>`;}
function sidebar(route){return `<aside class="sidebar" id="sidebar" aria-label="课程导航"><a class="brand" href="#/"><span class="brand-mark" aria-hidden="true">L</span><span>LoongSuite Go<small>THE ENGINEERING FIELD GUIDE</small></span></a><button class="search-launch" data-search><span>⌕　搜索手册</span><span class="key">⌘ K</span></button><nav class="utility-nav" aria-label="手册工具">${[['/','◈','学习路线'],['/start','01','从零开始 · 七小步'],['/official','官','对照官方文档'],['/source','⌘','源码地图'],['/labs','⌁','动手实验'],['/glossary','Aa','术语速查'],['/resources','↗','编写方法与资源']].map(([path,icon,label])=>`<a href="#${path}" class="${(route===path||path!=='/'&&route.startsWith(path+'/'))?'active':''}" ${(route===path||path!=='/'&&route.startsWith(path+'/'))?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><nav class="chapter-nav" aria-label="分阶课程">${['基础','机制','源码','二开'].map(stage=>`<div class="nav-label">${({基础:'01 / 建立基础',机制:'02 / 理解机制',源码:'03 / 阅读实现',二开:'04 / 开始二开'})[stage]}</div>${chapters.filter(c=>c.stage===stage).map(c=>`<a href="${chapterLink(c.id)}" class="${route===`/learn/${c.id}`?'active':''}" ${route===`/learn/${c.id}`?'aria-current="page"':''}><span class="chapter-number ${state.done.includes(c.id)?'done':''}">${state.done.includes(c.id)?'✓':number(c.id)}</span><span>${escape(c.title.split('：')[0])}</span></a>`).join('')}`).join('')}</nav><div class="sidebar-footer"><div>你的学习进度 <b data-progress-label>${state.done.length} / ${chapters.length}</b></div><div class="progress-track" role="progressbar" aria-label="已完成章节" aria-valuemin="0" aria-valuemax="${chapters.length}" aria-valuenow="${state.done.length}"><span style="width:${state.done.length/chapters.length*100}%"></span></div><span>进度与笔记保存在当前浏览器</span></div></aside><div class="mobile-scrim" data-close-menu></div>`;}
function shell(route,content,breadcrumb){return `${sidebar(route)}<div class="shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-menu aria-controls="sidebar" aria-expanded="false" aria-label="打开课程导航">☰</button><span>FIELD NOTES</span><b>${escape(breadcrumb)}</b></div><div class="top-actions"><span class="version">v1.15.0 · 固定源码</span><button class="icon-btn print-btn" data-print>打印 / PDF</button><button class="icon-btn" data-export title="导出学习笔记">导出笔记 ↓</button></div></header><main id="main" class="page" tabindex="-1">${content}${footer()}</main></div>`;}
function overview(){const stages=[['基础','先把 Go 与遥测说清楚','知道每个对象是谁、每个 ID 从哪来。'],['机制','跟随一次构建','从编译输入，走到能运行的探针。'],['源码','把图映射到函数','进入规则、跳板与运行时桥接。'],['二开','做一个能证明的改动','写规则、保语义、测兼容与回滚。']];return `<section class="hero"><div><div class="eyebrow">A GUIDED JOURNEY · 从 0 到能二开</div><h1>读懂插桩，<br>再亲手<em>改写。</em></h1><p>先从一个查房间的函数开始，弄清包、模块和构建。理解为什么需要观察代码，再一步步走到 LoongSuite 的真实实现。</p><div class="hero-footer"><a class="btn" href="${state.done.length?chapterLink(state.last):'#/start/1'}">${state.done.length?'继续学习':'从零开始 · 第一步'} <span>→</span></a><a class="btn light" href="#/official">跟着官方文档读 ↗</a><a class="btn light" href="#/source/deps">为什么要补依赖？ ↗</a><a class="btn light" href="#/source/preprocess">看三轮准备的实例动画 ↗</a></div></div><figure class="hero-figure"><div class="figure-label">先看两段时间，暂时不用背名词</div>${plainFlow([['源码','你编写的 .go 文件'],['构建','工具准备依赖并加工代码'],['运行','启动生成的程序，处理请求']],escape)}<figcaption class="figure-caption">LoongSuite 参与“构建”，把观察动作接入程序。<br>程序“运行”时，这些动作才真正记录请求。</figcaption></figure></section><div class="learning-meta"><span><b>7</b>入门小步</span><span><b>${chapters.length}</b>递进章节</span><span><b>${sourceMap.length}</b>源码入口</span><span><b>${labRegistry.length}</b>本地实验</span><span>阅读 + 实践约 ${Math.round(chapters.reduce((n,c)=>n+c.minutes,0)/60)} 小时，按自己的节奏推进</span></div><section><div class="section-head"><h2>从基础，到可验证的二开</h2><p>建议顺序阅读；已有基础可以直接进入对应章节。</p></div><div class="roadmap">${stages.map(([name,title,desc],i)=>`<section class="stage"><div class="stage-index">STAGE ${String(i+1).padStart(2,'0')}</div><h3>${title}</h3><p>${desc}</p><ul>${chapters.filter(c=>c.stage===name).map(c=>`<li><a href="${chapterLink(c.id)}"><span>${number(c.id)}</span>${escape(c.title.split('：')[0])} ${state.done.includes(c.id)?'✓':'↗'}</a></li>`).join('')}</ul></section>`).join('')}</div></section><aside class="practice-banner"><div><div class="eyebrow" style="color:var(--lime);margin-bottom:10px">LEARN BY CHANGING ONE THING</div><h2>从“我看懂了”，走到“我能证明”。</h2><p>改一次 context、一个版本区间、一段 hook。比较输入、输出与父子关系，再回到源码解释原因。</p></div><a href="#/labs" class="btn lime">打开实验台 →</a></aside><div class="promise-grid"><section><h2>你最终要交付什么？</h2><p>一个自己的自定义规则、匹配的 hook、原版与插桩的对照输出、一份兼容矩阵。毕业课会把这些组装成一次完整、可回滚的二开。</p><a href="${chapterLink('capstone')}">查看毕业项目与验收条件 →</a></section><section><h2>这份手册如何建立信任？</h2><p>源码链接固定到提交；页面交互标明是教学模型；实验独立记录真实执行状态。上游能力、已有 OTel 服务的兼容设计、未验证边界分别说明。</p><a href="#/resources">查看参考方法与来源 →</a></section></div><div class="callout"><b>学习约定</b>　会写基本 Go 函数即可开始。不要先把所有规则读一遍：先跑通一个小实验，再追踪它对应的编译路径。网站不执行 Go；实验包在你的本地终端运行。</div><div class="toolbar"><a class="btn light" href="./assets/labs.zip" download>下载本地实验包 ↓</a><a class="btn light" href="./offline.html" download>下载离线单文件手册 ↓</a><a class="btn light" href="./guide.md" download>下载 Markdown 正文 ↓</a></div>`;}
function renderSection(s,i){return `<section class="article-section" id="section-${i}"><h2>${escape(s.title)}</h2>${(s.paragraphs||[]).map(p=>`<p>${inline(p)}</p>`).join('')}${s.code?codeBlock(s.code,s.language):''}${s.note?`<aside class="callout">${inline(s.note)}</aside>`:''}</section>`;}
function chapterPage(c,print=false){const idx=chapters.indexOf(c);const checks=state.checks[c.id]||[],answers=state.answers[c.id]||{};const body=`<article class="article"><header class="chapter-header"><div class="eyebrow">LESSON ${number(c.id)} / ${c.stage}</div><h1>${escape(c.title)}</h1><p class="subtitle">${escape(c.subtitle)}</p><div class="chapter-info"><span>建议 ${c.minutes} 分钟 · 含实践</span><span>前置：${c.prerequisites.map(p=>chapters.find(x=>x.id===p)?.title.split('：')[0]||p).map(escape).join(' / ')}</span></div></header>${renderChapterBridge(c,{inline,escape})}<section class="outcomes"><h2>完成本章，你能做到</h2><ul>${c.outcomes.map(t=>`<li>${inline(t)}</li>`).join('')}</ul></section>${print?'':c.stage==='基础'?plainFlow([['普通函数','先理解原来的动作'],['观察代码','解释为何需要增加记录'],['自动接入','再到源码核实怎样做到']],escape):c.visual==='pipeline'?'':renderVisual(c.visual||'pipeline')}${c.sections.map(renderSection).join('')}<section class="article-section" id="source-reading"><h2>回到源码，带着问题读</h2><ol class="source-walk">${c.walkthrough.map(w=>`<li><div><a href="${escape(w.url)}" target="_blank" rel="noopener noreferrer">${escape(w.file)} ↗</a><p><strong>${escape(w.symbol)}</strong> · ${inline(w.task)}</p></div></li>`).join('')}</ol><a href="#/source">在源码地图中按调用路径定位 →</a></section><section class="article-section" id="lab"><div class="lab-box"><div class="eyebrow">TRY IT YOURSELF</div><h2>${escape(c.lab.title)}</h2><ol>${c.lab.steps.map(s=>`<li>${inline(s)}</li>`).join('')}</ol>${codeBlock(c.lab.command,'sh')}<div class="expected"><b>观察与验收：</b>${inline(c.lab.expected)}</div><p style="margin-top:16px;margin-bottom:0"><b>再改一步：</b>${inline(c.lab.challenge)}</p></div><div class="callout">可运行实验与真实验证状态见 <a href="#/labs">动手实验页</a>。正文内的概念代码若没有完整模块、import 和测试，是阅读示意，不是可直接运行的完整程序。</div></section><section class="article-section" id="quiz"><h2>先回答，再继续</h2>${c.quiz.map((q,i)=>`<fieldset class="quiz" data-quiz="${i}"><legend>${i+1}. ${escape(q.q)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="quiz-${c.id}-${i}" value="${j}" ${answers[i]===j?'checked':''}><span>${inline(o)}</span></label>`).join('')}<div class="feedback ${answers[i]===q.answer?'':'incorrect'}" ${answers[i]===undefined?'hidden':''}>${answers[i]===q.answer?'✓ 回答正确。':'再想一想。'} ${inline(q.explanation)}</div></fieldset>`).join('')}</section><section class="article-section" id="checkpoint"><h2>本章能力检查</h2><p>测验正确后，再确认你能独立完成以下动作。自评用于帮助学习，不代替实验执行记录。</p><div class="checkpoint">${c.checkpoint.map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${checks.includes(i)?'checked':''}><span>${inline(s)}</span></label>`).join('')}<div class="completion-row"><button class="btn" data-complete>${state.done.includes(c.id)?'✓ 已完成本章':'标记本章完成'}</button><small data-completion-help></small></div></div></section><section class="article-section" id="notes"><h2>写下你自己的解释</h2><label class="notes-label" for="chapter-notes"><span>用三句话说明：它解决什么、在哪里实现、怎样验证。</span><span data-note-status>自动保存到浏览器</span></label><textarea id="chapter-notes" class="notes" placeholder="我原先以为…\n通过实验发现…\n接下来我要在源码中确认…">${escape(state.notes[c.id]||'')}</textarea></section><section class="article-section" id="references"><h2>本章来源</h2><ul>${c.sources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a></li>`).join('')}</ul></section>${print?'':`<nav class="prev-next" aria-label="相邻章节">${idx>0?`<a href="${chapterLink(chapters[idx-1].id)}"><small>← 上一章</small>${escape(chapters[idx-1].title)}</a>`:'<a href="#/"><small>← 回到路线</small>查看学习全景</a>'}${idx<chapters.length-1?`<a href="${chapterLink(chapters[idx+1].id)}"><small>下一章 →</small>${escape(chapters[idx+1].title)}</a>`:'<a href="#/labs"><small>继续实践 →</small>打开实验与二开任务</a>'}</nav>`}</article>`;return print?body:`<div class="chapter-layout">${body}<aside class="toc" aria-label="本章目录"><h2>本章阅读路径</h2><a href="#chapter-bridge" data-scroll="chapter-bridge">先解释为什么与新名词</a>${c.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${escape(s.title)}</a>`).join('')}${[['source-reading','源码阅读'],['lab','动手练习'],['quiz','检查理解'],['checkpoint','能力检查'],['notes','我的笔记']].map(([id,t])=>`<a href="#${id}" data-scroll="${id}">${t}</a>`).join('')}<div class="toc-tools"><a href="./assets/labs.zip" download>下载实验包 ↓</a><a href="./offline.html" download>离线手册 ↓</a></div></aside></div>`;}
function sourcePage(selected=sourceMap[0]?.id){const s=sourceMap.find(x=>x.id===selected)||sourceMap[0];return renderSourcePage(s,sourceLessons[s.id],sourceMap,{inline,escape,codeBlock});}
function labsPage(){return `<div class="eyebrow">THE WORKBENCH / 运行以后再下结论</div><h1>一次只改变一个变量。</h1><p>实验在本地 Go 环境运行，页面不会调用业务接口，也不冒充在线 Go IDE。下载后先读 README，再按实验顺序进行。</p><div class="toolbar"><a class="btn" href="./assets/labs.zip" download>下载实验源码 ↓</a><a class="btn light" href="./lab-results.json" download>下载执行记录 ↓</a></div><div class="callout"><b>验证口径：</b>标准库机制实验、自定义 hook 编译实验、OTel SDK 实验分别标记。某个实验通过，不代表真实业务环境所有路径已验收。工具与依赖需要网络时，下载发生在你的终端。</div><div class="callout"><b>第一次学习，从 00 开始：</b>先运行普通 Go 函数，再逐个进入后面的机制实验。<code>run-all.sh</code> 是完整检查脚本，适合完成学习后使用。</div>${codeBlock('unzip labs.zip\ncd labs/00-start\ngo run .','sh')}${labRegistry.map((l,i)=>`<section class="lab-entry" id="lab-${i+1}"><div class="eyebrow">LAB ${escape(l.id.split('-')[0])} <span class="lab-status">${escape(l.status)}</span></div><h2>${escape(l.title)}</h2><p>${inline(l.goal)}</p>${codeBlock(l.command,'sh')}<div class="two-columns"><section><h3>观察哪一个证据？</h3><p>${inline(l.expected)}</p></section><section><h3>再做一个改动</h3><p>${inline(l.challenge)}</p></section></div><details><summary>展开参考解释与排查方向</summary><p>${inline(l.answer)}</p>${l.output?codeBlock(l.output,'text'):''}</details></section>`).join('')}<section class="article-section"><h2>从实验走向自己的规则</h2><p>先让只读 hook 正常编译、执行并保留原返回值；再把 OTel Span 接进去。修改参数、返回值、runtime/GLS 都应建立独立回归，不能用一个成功截图替代。</p><a href="${chapterLink('capstone')}" class="btn">进入毕业项目 →</a></section>`;}
function resourcesPage(){return `<div class="eyebrow">WRITING THE GUIDE / 编写方法与模板</div><h1>好的指南，先设计学习。</h1><div class="toolbar"><a class="btn light" href="./guide-authoring-resources.md" download>下载资源对比 ↓</a><a class="btn light" href="./chapter-template.md" download>下载章节模板 ↓</a></div><p>这些资源承担不同工作：skill 帮助组织与审稿，方法决定学习体验，文档框架负责呈现。下面是针对这份 Go 源码课程的选择依据，核对日期为 2026-10-27。</p><div class="callout"><b>本次选择：</b>teach 的分阶反馈 + Diátaxis 的内容分工 + Google 的读者与示例方法 + doc-coauthoring 的读者检验思路。界面采用原生 HTML/CSS/JS，便于离线与自定义图解；没有为了套模板而引入 React/Vue。下列安装命令是可选参考，本次没有全局安装这些 skill 或框架。</div><div class="table-scroll"><table class="reference-table"><thead><tr><th>你需要什么</th><th>优先考虑</th><th>选择原因</th></tr></thead><tbody><tr><td>从零学会一套技术</td><td>Diátaxis + 可验证实验</td><td>先设计读者动作和成功反馈，再补解释。</td></tr><tr><td>让 AI 协助写长文</td><td>doc-coauthoring</td><td>先整理证据与读者目标，再做无上下文读者检查。</td></tr><tr><td>长期维护内容型文档</td><td>Starlight</td><td>现成文档导航、搜索与组件，维护成本相对集中。</td></tr><tr><td>在文中加入复杂互动</td><td>VitePress / Docusaurus</td><td>分别利用 Vue / React 组件；选择团队熟悉的生态。</td></tr><tr><td>短篇但深入的互动手册</td><td>原生网页 + 小组件</td><td>可离线、无需构建依赖，交互围绕学习问题设计。</td></tr></tbody></table></div>${resources.map(r=>`<section class="resource-item"><div><span class="tag">${escape(r.kind)}</span><h2 style="font-size:20px;margin:12px 0 6px">${escape(r.name)}</h2><a href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">官方 / GitHub ↗</a></div><div><p><b>适合：</b>${inline(r.fit)}</p><p><b>局限：</b>${inline(r.limit)}</p><p><b>本指南的借鉴：</b>${inline(r.adopt)}</p><a href="${escape(r.docs)}" target="_blank" rel="noopener noreferrer">阅读原始说明 ↗</a>${r.install?codeBlock(r.install,'sh'):''}</div></section>`).join('')}<section class="article-section"><h2>一份可以复用的教学章节模板</h2><p>模板的关键是让每一步产出证据，而不是每章重复“概述、特点、总结”。复制后，用具体函数、版本和输出替换泛化内容。</p>${codeBlock(lessonTemplate,'markdown')}</section><section class="article-section"><h2>本手册的质量门槛</h2><ol><li>每个术语在第一次出现时解释，并能连回具体源码。</li><li>源码路径存在，链接固定到提交，阅读问题有明确目标。</li><li>可运行代码必须有命令、前置、预期和真实状态；示意代码清楚标注。</li><li>图解表达因果，不用装饰动画替代解释。</li><li>完成不等于读过：你能复现实验、修改输入，再解释差异。</li></ol></section>`;}
function glossaryPage(){return `<div class="eyebrow">THE GLOSSARY / 快速找回概念</div><h1>让每个名词都有落点。</h1><p>阅读源码时遇到陌生词，先确认它属于编译期、运行时，还是采集后端。不要把同一层的对象混作另一层的能力。</p><label class="sr-only" for="glossary-search">筛选术语</label><input class="filter-input" id="glossary-search" type="search" placeholder="搜索 AST、carrier、GLS…"><dl class="glossary">${glossary.map(([term,def])=>`<div data-term><dt>${escape(term)}</dt><dd>${inline(def)}</dd></div>`).join('')}</dl>`;}
function getRoute(){const raw=location.hash.slice(1)||'/';return raw.startsWith('/')?raw:'/';}
function render(){disposeLessonDemos();const route=getRoute(),[_,type,id]=route.split('/');currentRoute=route;let content,label;if(type==='learn'){const c=chapters.find(c=>c.id===id);if(!c){location.hash='/';return;}state.last=c.id;persist();content=chapterPage(c);label=`${number(c.id)} / ${c.title.split('：')[0]}`;}else if(type==='start'){content=renderZeroPage(id,{inline,escape,codeBlock});label='从零开始 · 七小步';}else if(type==='official'){content=renderOfficialPage(id,{inline,escape})
label='对照官方文档'
}else if(type==='source'){content=sourcePage(id);label='源码地图';}else if(type==='labs'){content=labsPage();label='动手实验';}else if(type==='resources'){content=resourcesPage();label='编写方法与资源';}else if(type==='glossary'){content=glossaryPage();label='术语速查';}else{content=overview();label='学习路线';}
 app.innerHTML=shell(route,content,label);document.title=`${label} · LoongSuite Go 学习手册`;bindVisual(app);disposeLessonDemos=bindLessonDemos(app);bindGeneral();if(type==='learn')bindChapter(chapters.find(c=>c.id===id));if(type==='source')bindSource();if(type==='glossary')$('#glossary-search').addEventListener('input',e=>app.querySelectorAll('[data-term]').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(e.target.value.toLowerCase())));window.scrollTo(0,0);
}
function bindGeneral(){app.querySelectorAll('[data-search]').forEach(b=>b.onclick=openSearch);app.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(b.closest('.code-frame').querySelector('[data-raw]').textContent));app.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});app.querySelectorAll('[data-export]').forEach(b=>b.onclick=exportNotes);app.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>window.print());app.querySelector('[data-menu]')?.addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('open');$('.mobile-scrim').classList.toggle('open',open);$('[data-menu]').setAttribute('aria-expanded',String(open));});app.querySelector('[data-close-menu]')?.addEventListener('click',()=>{$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('open');$('[data-menu]').setAttribute('aria-expanded','false');});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制');}catch{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?'已复制':'请选中代码后复制');}}
function eligible(c){return c.quiz.every((q,i)=>state.answers[c.id]?.[i]===q.answer)&&c.checkpoint.every((_,i)=>(state.checks[c.id]||[]).includes(i));}
function updateCompletion(c){const ok=eligible(c),done=state.done.includes(c.id);$('[data-complete]').disabled=!ok&&!done;$('[data-completion-help]').textContent=done?'完成记录已保存在当前浏览器。':ok?'测验与能力检查已完成，可以进入下一章。':'答对本章测验，并确认全部能力检查后解锁。';}
function bindChapter(c){app.querySelectorAll('[data-quiz]').forEach(field=>field.addEventListener('change',e=>{const i=Number(field.dataset.quiz),j=Number(e.target.value);state.answers[c.id]||={};state.answers[c.id][i]=j;persist();const feedback=field.querySelector('.feedback');feedback.hidden=false;feedback.classList.toggle('incorrect',j!==c.quiz[i].answer);feedback.innerHTML=`${j===c.quiz[i].answer?'✓ 回答正确。':'再想一想。'} ${inline(c.quiz[i].explanation)}`;updateCompletion(c);}));app.querySelectorAll('[data-check]').forEach(input=>input.addEventListener('change',()=>{const i=Number(input.dataset.check),v=new Set(state.checks[c.id]||[]);input.checked?v.add(i):v.delete(i);state.checks[c.id]=[...v];persist();updateCompletion(c);}));$('[data-complete]').onclick=()=>{if(!eligible(c))return;if(!state.done.includes(c.id))state.done.push(c.id);persist();render();toast('已完成本章，学习进度已保存。');};$('#chapter-notes').addEventListener('input',e=>{state.notes[c.id]=e.target.value;persist();$('[data-note-status]').textContent='已保存';});updateCompletion(c);}
function bindSource(){app.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{location.hash=`/source/${b.dataset.source}`;});$('#source-filter')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();app.querySelectorAll('[data-source]').forEach(n=>{const s=sourceMap.find(s=>s.id===n.dataset.source);n.hidden=![s.title,s.path,s.symbol,s.role,sourceLessons[s.id]?.title,sourceLessons[s.id]?.plain].join(' ').toLowerCase().includes(q);});const empty=app.querySelector('.source-no-results');if(empty)empty.hidden=Array.from(app.querySelectorAll('[data-source]')).some(n=>!n.hidden);});}
const dialog=$('#search-dialog');function openSearch(){dialog.showModal();$('#global-search').value='';search('');$('#global-search').focus();}$('#close-search').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dialog.open?dialog.close():openSearch();}});$('#global-search').addEventListener('input',e=>search(e.target.value));
function demoSearchText(kind,id){const d=lessonDemos[kind]?.[id];return d?[d.title,d.scenario,...d.cases.flatMap(c=>c.frames.flatMap(f=>[f.title,f.explain,f.code.text]))].join(' '):'';}
function search(q){const word=q.toLowerCase().trim();const hits=[];
 for(const [i,s]of zeroSteps.entries()){const text=[s.title,s.question,...s.paragraphs,...s.terms.map(t=>t.term+' '+t.meaning),demoSearchText('zero',s.id)].join(' ');if(!word||text.toLowerCase().includes(word))hits.push({title:`从零 ${i+1} · ${s.title}`,url:`#/start/${i+1}`,detail:s.question});}
 for(const c of chapters){const text=[c.title,c.subtitle,...c.sections.flatMap(s=>[s.title,...s.paragraphs]),...c.bridge.terms.map(t=>t.term+' '+t.meaning),demoSearchText('chapter',c.id)].join(' ');if(!word||text.toLowerCase().includes(word)){const at=text.toLowerCase().indexOf(word);hits.push({title:`${number(c.id)} · ${c.title}`,url:chapterLink(c.id),detail:word?text.slice(Math.max(0,at-25),at+100):c.subtitle});}}
 for(const s of sourceMap){const lesson=sourceLessons[s.id];if(word&&[s.title,s.path,s.symbol,s.role,lesson.title,lesson.plain,...lesson.terms.map(t=>t.term+' '+t.meaning),demoSearchText('source',s.id)].join(' ').toLowerCase().includes(word))hits.push({title:lesson.title,url:`#/source/${s.id}`,detail:s.path});}
 for(const p of officialPages)if(word&&[p.title,p.group.title,p.says,p.gap,p.question].join(' ').toLowerCase().includes(word))hits.push({title:`官方文档对照 · ${p.group.title} · ${p.title}`,url:`#/official/${p.id}`,detail:p.path})
 $('#search-results').innerHTML=hits.length?hits.slice(0,30).map(x=>`<a href="${x.url}">${escape(x.title)}<small>${escape(x.detail)}</small></a>`).join(''):'<p class="empty">没有匹配结果。试试 module、依赖、context、采样或 hook。</p>';$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>dialog.close());}
function exportNotes(){let text='# LoongSuite Go 学习记录\n\n源码版本：v1.15.0 / cac400935add57d8219122ba32857b8f55ac6eb1\n\n';for(const c of chapters){text+=`## ${number(c.id)} ${c.title}\n\n状态：${state.done.includes(c.id)?'已完成':'学习中 / 未完成'}\n\n${state.notes[c.id]||'（暂无笔记）'}\n\n`;for(const [i,item]of c.checkpoint.entries())text+=`- [${(state.checks[c.id]||[]).includes(i)?'x':' '}] ${item}\n`;text+='\n';}const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='loongsuite-learning-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习笔记已导出');}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
window.addEventListener('hashchange',render);render();
